oxy_webhelp_navlinks = {"sap_hana_recovery-d39307e41335":{"topics":[{"title":"SAP HANA recovery using <span class=\"ph\">RSC<\/span> versus SAP HANA Studio","shortdesc":"<p class=\"shortdesc\">Information about the key differences between recovering an SAP HANA database using             <span class=\"ph\">RSC<\/span> and using SAP HANA Studio.<\/p>","href":"saas\/sap_hana_recovery_rubrik_vs_studio.html","attributes":{"data-id":"sap_hana_recovery_rubrik_vs_studio"},"menu":{"hasChildren":false},"tocID":"sap_hana_recovery_rubrik_vs_studio-d39307e41351","topics":[]},{"title":"SAP HANA recovery using <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides various SAP HANA recovery options, including         point-in-time, full snapshot, and system copy restores. These options makes sure data         integrity and quick recovery to original or target databases, considering impacts on         SYSTEMDB and ongoing backups.<\/p>","href":"saas\/sap_hana_recovery_using_rsc.html","attributes":{"data-id":"sap_hana_recovery_using_rsc"},"menu":{"hasChildren":false},"tocID":"sap_hana_recovery_using_rsc-d39307e41368","next":"sap_hana_recovery_using_rsc-d39307e41368"},{"title":"SAP HANA recovery using SAP HANA Studio","shortdesc":"<p class=\"shortdesc\">SAP HANA Studio provides a user interface for performing database recovery         operations. This method primarily involves direct interaction with database backups and         logs, either through a backup catalog or by directly specifying file system         locations.<\/p>","href":"saas\/sap_hana_recovery_studio.html","attributes":{"data-id":"sap_hana_recovery_studio"},"menu":{"hasChildren":false},"tocID":"sap_hana_recovery_studio-d39307e41419","next":"sap_hana_recovery_studio-d39307e41419"},{"title":"SAP HANA recovery using storage snapshots","shortdesc":"<p class=\"shortdesc\">You can use the SAP HANA storage snapshot to recover your SAP HANA databases. Storage         snapshots are fast, encrypted, have negligible network load, and capture the entire data         area at a particular point in time. Use <span class=\"ph\">RSC<\/span> to recover SAP HANA databases         from storage snapshots on Azure.<\/p>","href":"saas\/sap_hana_storage_snapshot_recovery.html","attributes":{"data-id":"sap_hana_storage_snapshot_recovery"},"menu":{"hasChildren":false},"tocID":"sap_hana_storage_snapshot_recovery-d39307e41553","next":"sap_hana_storage_snapshot_recovery-d39307e41553"},{"title":"Restoring a database from a Managed Volume snapshot","shortdesc":"<p class=\"shortdesc\">Restore a database from an exported Managed Volume snapshot using <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/saphana_restoring_db_mv_snapshot.html","attributes":{"data-id":"saphana_restoring_db_mv_snapshot"},"menu":{"hasChildren":false},"tocID":"saphana_restoring_db_mv_snapshot-d39307e41592","topics":[]}]}};